for (const marca in marcasConfig) {
  if (productoNormalizado.includes(marca)) {
    marcaEncontrada = marca;
    break;
  }
}

// Si se encontró una marca, actualizar businesstypeid y grupoCaptura
if (marcaEncontrada) {
  item.businesstypeid = marcasConfig[marcaEncontrada].businesstypeid;
  item.grupoCaptura = marcasConfig[marcaEncontrada].grupoCaptura;
}

// Detectar si el lead es de FIAT (no está en marcasConfig porque necesita
// businesstypeid distinto según usado/pago, no un único valor fijo)
const esFiat = (item.grupoCaptura || '').toLowerCase() === 'fiat'
  || productoNormalizado.includes('fiat');

// Asignar origen y businesstypeid:
// 1) Si el cliente quiere comprar un usado, prioriza el código/tipo de usado
// 2) Si no, se calcula según la forma de pago (Financiado/Contado = Convencional, Plan de Ahorro = Plan)
if (item.compraUsado === true) {
  item.origen = 'G5CAS2WTK2M3AYUBK';
  if (esFiat) {
    item.businesstypeid = '2';
  }
} else {
  const pagoNormalizado = (item.pago || '').toLowerCase();
  if (pagoNormalizado.includes('plan de ahorro')) {
    item.origen = 'G5QF5QTGO159P9AGW';
    if (esFiat) {
      item.businesstypeid = '8';
    }
  } else if (pagoNormalizado.includes('financiado') || pagoNormalizado.includes('contado')) {
    item.origen = 'G5QHNEP54ND24DX5W';
    if (esFiat) {
      item.businesstypeid = '7';
    }
  } else {
    // Fallback si no hay forma de pago registrada todavía
    item.origen = 'FV8QZM0HS9EB4ZDVK';
    // businesstypeid queda como estaba (sin diferenciar) si no hay pago aún
  }
}

// Si el lead tiene publicación de MercadoLibre, antepone el link al resumen
const esML = Boolean(item.meli_publicacion_id);
const resumenFinal = esML
  ? "ML: " + ($('buscarTelefono').first().json?.item_permalink || "") + " | " + (item.resumen || "No definido")
  : (item.resumen || "No definido");

return {
  json: {
    ...item,
    asesor_nombre: asesor?.nombre || null,
    asesor_telefono: asesor?.telefono || null,
    asesor_email: asesor?.email || null,
    hasAdvisor: Boolean(asesor?.telefono),
    contentVariables: JSON.stringify({
      "1": item.nombreDeclarado || item.name || "No definido",
      "2": item.number || "No definido",
      "3": item.ProductoInteres || "No definido",
      "4": asesor?.boca_venta || "No definida",
      "5": resumenFinal
    })
  }
};

