parameters.jsCode:
const input = $input.all()[0].json;

// Datos originales recibidos por el workflow
let originalInput = {};

try {
  originalInput = $('When Executed by Another Workflow').first().json;
} catch (error) {
  originalInput = {};
}

// Función para parsear query cuando viene como string
function parseQueryString(queryString) {
  const result = {};

  if (!queryString || typeof queryString !== 'string') {
    return result;
  }

  const patterns = [
    { key: 'origin', regex: /origin:\s*([^,]+)/i },
    { key: 'businesstypeid', regex: /businesstypeid:\s*([^,]+)/i },
    { key: 'grupoCaptura', regex: /grupoCaptura:\s*([^,]+?)(?=,\s*modelo:|$)/i },
    { key: 'modelo', regex: /modelo:\s*([^,]+?)(?=,\s*pago:|$)/i },
    { key: 'pago', regex: /pago:\s*([^,]+?)(?=,\s*usado:|$)/i },
    { key: 'usado', regex: /usado:\s*([^,]+?)(?=,\s*interes:|$)/i },
    { key: 'interes', regex: /interes:\s*([^,]+)/i }
  ];

  patterns.forEach(({ key, regex }) => {
    const match = queryString.match(regex);
    if (match) {
      result[key] = match[1].trim();
    }
  });

  return result;
}

// Detectar si query es string u objeto
let parsedQuery = {};

if (typeof originalInput.query === 'string') {
  parsedQuery = parseQueryString(originalInput.query);
} else if (typeof originalInput.query === 'object' && originalInput.query !== null) {
  parsedQuery = {
    origin: originalInput.query.origin,
    businesstypeid: originalInput.query.businesstypeid,
    grupoCaptura: originalInput.query.grupoCaptura,
    modelo: originalInput.query.producto || originalInput.query.modelo,
    pago: originalInput.query.pago,
    usado: originalInput.query.usado,
    interes: originalInput.query.interes
  };
}

// Limpiar valores undefined / null
function cleanValue(value) {
  if (
    value === undefined ||
    value === null ||
    value === 'undefined' ||
    value === 'null'
  ) {
    return '';
  }

  return String(value).trim();
}

// Valores comerciales
const modelo =
  cleanValue(parsedQuery.modelo) ||
  cleanValue(originalInput.ProductoInteres) ||
  cleanValue(originalInput.producto) ||
  cleanValue(originalInput.modelo);

const pago =
  cleanValue(parsedQuery.pago) ||
  cleanValue(originalInput.pago);

const usado =
  cleanValue(parsedQuery.usado) ||
  cleanValue(originalInput.usado);

const interes =
  cleanValue(parsedQuery.interes) ||
  cleanValue(originalInput.interes) ||
  (modelo && pago && usado ? 'alto' : 'bajo');

const origin =
  cleanValue(parsedQuery.origin) ||
  cleanValue(originalInput.origin);

const businesstypeid =
  cleanValue(parsedQuery.businesstypeid) ||
  cleanValue(originalInput['businesstypeid ']) ||
  cleanValue(originalInput.businesstypeid);

const grupoCaptura =
  cleanValue(parsedQuery.grupoCaptura) ||
  cleanValue(originalInput['grupoCaptura ']) ||
  cleanValue(originalInput.grupoCaptura);

// Construir pilot_notes
const pilot_notes = `Modelo: ${modelo || 'No especificado'}
Pago: ${pago || 'No especificado'}
Usado: ${usado || 'No especificado'}
Interés: ${interes}`;

// Output final
const output = {
  goodLead: originalInput.goodLead,

  name: cleanValue(originalInput.name),
  nombreDeclarado: cleanValue(originalInput.nombreDeclarado),

  number: cleanValue(originalInput.number),
  from: cleanValue(originalInput.number),

  idConversation: cleanValue(originalInput.idConversation),

  origin: origin,

  businesstypeid: businesstypeid,

  grupoCaptura: grupoCaptura,

  producto: modelo,

  ProductoInteres:
    cleanValue(originalInput.ProductoInteres) ||
    modelo,

  usado: usado,

  pago: pago,

  interes: interes,

  resumen: cleanValue(originalInput.resumen),

  testDrive: originalInput.testDrive,
  comentarioTestDrive: cleanValue(originalInput.comentarioTestDrive),

  reunionAsesor: originalInput.reunionAsesor,

  sucursal: cleanValue(originalInput.sucursal),

  compraUsado: originalInput.compraUsado,

  pilot_notes: pilot_notes,

  // Datos devueltos por Pilot
  pilotSuccess: input.success ?? false,
  pilotMessage: input.message || '',
  pilotWelcomeId: input.data?.welcome_id || '',
  pilotProspectId: input.data?.prospect_id || '',
  pilotAssignedUserId: input.data?.welcome_asigned_user_id || '',
  pilotAssignedUserName: input.data?.welcome_assigned_user_fullname || '',
  pilotAssignedUserEmail: input.data?.welcome_assigned_user_email || '',
  pilotAssignedBranchId: input.data?.welcome_asigned_branch_id || '',
  pilotAssignedBranch: input.data?.welcome_asigned_branch || ''
};

return {
  json: output
};
